// Restore the latest fenced destination state; never revive stale OAuth after a failed cutover.
import fs from'node:fs';import crypto from'node:crypto';import{execFileSync}from'node:child_process';
const cfg=JSON.parse(fs.readFileSync(process.argv[2])),response=JSON.parse(fs.readFileSync(process.argv[3]));if(response.status!=='passed'||!response.result.fenced)throw Error('Destination not fenced');if(!response.result.applied)process.exit(0);
const v=response.result.envelope,kind='business-return';if(v.session!==cfg.session||v.kind!==kind||v.purpose!=='lmg-production-ops-v1')throw Error('Returned state identity');
const key=crypto.privateDecrypt({key:fs.readFileSync(cfg.private_key),oaepHash:'sha256',padding:crypto.constants.RSA_PKCS1_OAEP_PADDING},Buffer.from(v.wrapped_key,'base64')),data=Buffer.from(v.ciphertext,'base64'),cipher=crypto.createDecipheriv('aes-256-gcm',key,Buffer.from(v.nonce,'base64'));cipher.setAAD(Buffer.from(v.purpose+'\n'+cfg.session+'\n'+kind));cipher.setAuthTag(data.subarray(-16));const p=JSON.parse(Buffer.concat([cipher.update(data.subarray(0,-16)),cipher.final()]));
const valid=name=>/^(private\/(config\.yaml|runtime\.env|pool-runtime\.json|plus-config\.json|plus-admin\.key)|auths\/[^/.][^/]*\.json|data\/pool\.sqlite|plus\/(usage\.sqlite|data\.key))$/.test(name)&&!name.includes('..');
for(const[n,r]of Object.entries(p.files)){const b=Buffer.from(r.data,'base64');if(!valid(n)||b.length!==r.size||crypto.createHash('sha256').update(b).digest('hex')!==r.sha256)throw Error('Returned file rejected')}
const root='/opt/yifu-cpa';for(const f of fs.readdirSync(root+'/auths'))if(!p.files['auths/'+f])fs.renameSync(root+'/auths/'+f,cfg.directory+'/rollback-superseded-'+f);
for(const[n,r]of Object.entries(p.files)){const path=root+'/'+n;if(n.endsWith('.sqlite'))for(const s of ['-wal','-shm'])fs.rmSync(path+s,{force:true});fs.writeFileSync(path+'.next',Buffer.from(r.data,'base64'),{mode:0o600});fs.chmodSync(path+'.next',0o600);fs.renameSync(path+'.next',path)}
execFileSync('/bin/chown',['-R','cpa:cpa',root],{stdio:'ignore'});console.log(JSON.stringify({latest_destination_state_restored:true,files:Object.keys(p.files).length}));
